CREATE OR REPLACE FUNCTION public.mha_company_recipe_catalog(p_store_id bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_company bigint;\nbegin\n select company_id into v_company from public.mha_current_store_context(p_store_id);\n if not public.mha_has_permission(v_company,'recipe','VIEW') then raise exception 'Recipe access denied' using errcode='42501';end if;\n return jsonb_build_object(\n 'products',coalesce((select jsonb_agg(jsonb_build_object('id',id,'sku_code',sku_code,'sku_name',sku_name) order by sku_code) from public.production_sku where company_id=v_company and is_active),'[]'::jsonb),\n 'variants',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'production_sku_id',v.production_sku_id,'variant_name',v.variant_name,'variant_code',v.variant_code) order by v.variant_code) from public.product_variant v join public.production_sku p on p.id=v.production_sku_id where p.company_id=v_company and p.is_active and v.is_active),'[]'::jsonb),\n 'ingredients',coalesce((select jsonb_agg(jsonb_build_object('id',id,'sku_code',sku_code,'sku_name',sku_name,'recipe_uom',recipe_uom) order by sku_code) from public.inventory_sku where company_id=v_company and is_active),'[]'::jsonb),\n 'base_recipes',coalesce((select jsonb_agg(jsonb_build_object('production_sku_id',r.production_sku_id,'inventory_sku_id',r.inventory_sku_id,'quantity',r.quantity)) from public.product_recipe r join public.production_sku p on p.id=r.production_sku_id join public.inventory_sku i on i.id=r.inventory_sku_id where p.company_id=v_company and i.company_id=v_company),'[]'::jsonb),\n 'variant_recipes',coalesce((select jsonb_agg(jsonb_build_object('product_variant_id',r.product_variant_id,'inventory_sku_id',r.inventory_sku_id,'quantity',r.quantity)) from public.variant_recipe r join public.product_variant v on v.id=r.product_variant_id join public.production_sku p on p.id=v.production_sku_id join public.inventory_sku i on i.id=r.inventory_sku_id where p.company_id=v_company and i.company_id=v_company),'[]'::jsonb)\n );\nend $function$\n